class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        int m = rolls.length;
        int totalSum = mean * (n + m);
        int existingSum = 0;
        for (int r : rolls) existingSum += r;
        int missingSum = totalSum - existingSum;
        if (missingSum < n || missingSum > 6 * n) return new int[0];
        int[] result = new int[n];
        int base = missingSum / n;
        int extra = missingSum % n;
        for (int i = 0; i < n; i++) {
            result[i] = base + (i < extra ? 1 : 0);
        }
        return result;
    }
}

